NSArray<NSString *> *SaoqiangWCAssetsPackBaseNames(void) {
    static NSArray<NSString *> *bases;
    static dispatch_once_t once;
    dispatch_once(&once, ^{
        NSString *text = [NSString stringWithUTF8String:SQPackNameText];
        NSMutableArray *list = [NSMutableArray new];
        for (NSString *line in [text componentsSeparatedByString:@"\n"]) {
            if (!line.length || line.length > 120) continue;
            [list addObject:line];
        }
        bases = [list copy];
    });
    return bases;
}

NSArray<NSString *> *SaoqiangWCAssetsPackNameCandidates(void) {
    static NSArray<NSString *> *candidates;
    static dispatch_once_t once;
    dispatch_once(&once, ^{
        // Shape-major, most likely first: a pack stores the @3x set, then @2x,
        // then any bare background names, then the Dark pair. Asking in that
        // order means the byte budget is spent on real files rather than on
        // misses at the tail.
        NSArray<NSArray<NSString *> *> *shapes = @[
            @[@"@3x", @".png"], @[@"@2x", @".png"], @[@"", @".png"],
            @[@"_Dark@3x", @".png"], @[@"_Dark@2x", @".png"], @[@"_Dark", @".png"],
            @[@"", @".svg"], @[@"@3x", @".svg"], @[@"@2x", @".svg"],
        ];
        NSMutableArray *list = [NSMutableArray arrayWithCapacity:28000];
        for (NSArray<NSString *> *shape in shapes) {
            BOOL dark = [shape[0] hasPrefix:@"_Dark"];
            for (NSString *base in SaoqiangWCAssetsPackBaseNames()) {
                if (dark && [base hasSuffix:@"_Dark"]) continue;
                [list addObject:[[base stringByAppendingString:shape[0]] stringByAppendingString:shape[1]]];
            }
        }
        candidates = [list copy];
    });
    return candidates;
}
